INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朱珍取濮州，朱裕奔郓", "start_year": 887, "end_year": 887, "time_original": "光启三年十月丁未", "dynasty": "唐", "description": "朱珍攻取濮州，刺史朱裕奔郓；朱珍继续进攻郓州。", "phases": [], "location_name": "濮州、郓州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9ea9bf66-e67b-5392-8d98-328fefcba18a"}, {"title": "朱瑄设伏击退汴军", "start_year": 887, "end_year": 887, "time_original": "濮州失守后；具体日未载", "dynasty": "唐", "description": "朱瑄使朱裕诈称可为内应，诱朱珍夜进郓州；朱瑄开门纳汴军后关门袭杀，汴军退去。", "phases": [], "location_name": "郓州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7445efc7-d981-5814-b039-f776ee777160"}, {"title": "朱瑄复取曹州任郭词刺史", "start_year": 887, "end_year": 887, "time_original": "击退汴军后；具体日未载", "dynasty": "唐", "description": "朱瑄乘胜复取曹州，任其部属郭词为刺史。", "phases": [], "location_name": "曹州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d023dbfc-1a58-5a22-bd78-794b1da83d62"}, {"title": "皇子升封益王", "start_year": 887, "end_year": 887, "time_original": "光启三年十月甲寅", "dynasty": "唐", "description": "朝廷立皇子升为益王。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "fd3ff0c6-e7ae-54fe-9c25-de1e34849c9a"}, {"title": "杜稜等攻取常州", "start_year": 887, "end_year": 887, "time_original": "光启三年十月；具体日未载", "dynasty": "唐", "description": "杜稜等攻取常州，丁从实逃往海陵。", "phases": [], "location_name": "常州、海陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a16f9fda-3d8d-5bdf-b913-482dfb530b2d"}, {"title": "钱镠迎周宝至杭州", "start_year": 887, "end_year": 887, "time_original": "光启三年十月；具体日未载", "dynasty": "唐", "description": "钱镠奉周宝返回杭州，以部将礼节出城迎接，并将其交属高鞬。", "phases": [], "location_name": "杭州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b6df8181-6281-5e20-b074-705d607cdc48"}, {"title": "广陵长期围城饥荒", "start_year": 887, "end_year": 887, "time_original": "杨行密围广陵近半年至光启三年十月", "dynasty": "唐", "description": "杨行密围广陵近半年，秦彦、毕师铎多次出战不利；城中食物耗尽，民众大量饿死，宣州军又掠人贩卖和杀害。", "phases": [], "location_name": "广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "0ed7593c-267a-55ad-a1ab-f6a93f7c4d08"}, {"title": "张审威潜登广陵开门", "start_year": 887, "end_year": 887, "time_original": "光启三年十月己巳夜至次晨", "dynasty": "唐", "description": "杨行密久攻广陵不下，曾想撤军。张审威率兵伏于西壕，趁守军换班登城开门，守军溃散。", "phases": [], "location_name": "广陵西壕、城门", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9ee9b3d3-661f-5e9b-92e2-19d5f24703c8"}, {"title": "秦彦毕师铎逃往东塘", "start_year": 887, "end_year": 887, "time_original": "广陵城门被打开后；具体日未载", "dynasty": "唐", "description": "秦彦、毕师铎向王奉仙问计后，从开化门出逃至东塘。", "phases": [], "location_name": "广陵开化门、东塘", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "bf116a90-aae5-52e6-9cb5-7f286994434c"}, {"title": "杨行密入广陵自称淮南留后", "start_year": 887, "end_year": 887, "time_original": "秦彦毕师铎出逃后；具体日未载", "dynasty": "唐", "description": "杨行密率军入广陵，自称淮南留后。", "phases": [], "location_name": "广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e6d14d5d-ea05-5095-91a7-f227e2497f7f"}, {"title": "杨行密斩梁缵，韩问自尽", "start_year": 887, "end_year": 887, "time_original": "杨行密入广陵后；具体日未载", "dynasty": "唐", "description": "杨行密以梁缵转为秦彦、毕师铎所用为由将其斩杀；韩问闻讯投井而死。", "phases": [], "location_name": "广陵戟门", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d4b7a65c-e133-517d-a929-c3aaea516517"}, {"title": "高愈摄副使改殡高骈，杨行密赈广陵", "start_year": 887, "end_year": 887, "time_original": "杨行密入广陵后；具体日未载", "dynasty": "唐", "description": "杨行密任高骈从孙高愈摄副使，令其改殡高骈及亲族；又从西寨运米赈济城中幸存者。", "phases": [], "location_name": "广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1f9f9ee3-632c-5f7c-b593-92d03766b860"}, {"title": "秦宗权遣秦宗衡争扬州", "start_year": 887, "end_year": 887, "time_original": "光启三年十一月辛未", "dynasty": "唐", "description": "秦宗权遣弟秦宗衡率军渡淮，孙儒为副，张佶、刘建锋、马殷及秦彦晖随军；辛未抵广陵城西，取得杨行密尚未入城的辎重。", "phases": [], "location_name": "广陵城西", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "79bf6aa7-ff73-509c-908b-4e8c55bca732"}, {"title": "秦彦毕师铎转投秦宗衡", "start_year": 887, "end_year": 887, "time_original": "光启三年十一月辛未后", "dynasty": "唐", "description": "秦彦、毕师铎逃至东塘，张雄不予收留；二人拟渡江往宣州，接秦宗衡邀请后折返与其合军。", "phases": [], "location_name": "东塘、广陵城西", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7c073de4-12fb-519a-bfd3-24adeaebb008"}, {"title": "孙儒杀秦宗衡", "start_year": 887, "end_year": 887, "time_original": "光启三年十一月甲戌", "dynasty": "唐", "description": "秦宗权召秦宗衡返蔡拒朱全忠，孙儒托病不行；秦宗衡屡催，孙儒于席间杀秦宗衡，并将首级送给朱全忠。", "phases": [], "location_name": "广陵城西", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1aa871f1-4377-5e42-8721-6ae54159e036"}, {"title": "安仁义降杨行密并领骑兵", "start_year": 887, "end_year": 887, "time_original": "秦宗衡被杀后；具体日未载", "dynasty": "唐", "description": "秦宗衡部将安仁义归降杨行密，杨行密将骑兵委其统领，位在田頵之上。", "phases": [], "location_name": "广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "728f37db-dccb-5759-b441-c6264a9606e1"}, {"title": "孙儒与秦彦毕师铎袭高邮", "start_year": 887, "end_year": 887, "time_original": "光启三年十一月后；具体日未载", "dynasty": "唐", "description": "孙儒分兵掠邻州，军众增加；因广陵城下缺粮，与秦彦、毕师铎合军袭高邮。", "phases": [], "location_name": "高邮", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "12ebf067-acf2-5c32-80ce-91a1424685c8"}, {"title": "朱珍与李唐宾争执后获朱全忠宽宥", "start_year": 887, "end_year": 887, "time_original": "光启三年十一月丙子夜前后", "dynasty": "唐", "description": "朱全忠因朱珍未经请命迎妻而愤怒，曾拟召回朱珍、让李唐宾代领其军；敬翔劝止。朱珍、李唐宾互疑，先后离军赴大梁；朱全忠未治罪，遣二人回濮州。", "phases": [], "location_name": "大梁、濮州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4fb38f7d-7b0a-5b6d-9ea3-2f3e6f09c21b"}, {"title": "朱全忠常咨敬翔军政", "start_year": 887, "end_year": 887, "time_original": "光启三年十一月前后；具体日未载", "dynasty": "唐", "description": "《通鉴》称敬翔能推知朱全忠意图，朱全忠常就军机、民政询问他。", "phases": [], "location_name": "宣武", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "680a1ca8-247a-5fae-835b-0067ac519f0e"}, {"title": "孙儒攻陷高邮，张神剑返扬州", "start_year": 887, "end_year": 887, "time_original": "光启三年辛巳至丙戌；月份未重标", "dynasty": "唐", "description": "高邮镇遏使张神剑先率少数部众逃归扬州；丙戌孙儒攻陷高邮，原文称“屠高邮”。", "phases": [], "location_name": "高邮、扬州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "fc622ef7-fd39-53fb-b1a6-a2e7a6eb807b"}, {"title": "杨行密坑杀高邮残兵及张神剑", "start_year": 887, "end_year": 887, "time_original": "光启三年戊子至次日；月份未重标", "dynasty": "唐", "description": "高邮残兵突围到广陵，杨行密疑其生变，分配诸将后一夜全部坑杀；次日又杀张神剑。", "phases": [], "location_name": "广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "32f2c4cc-91de-56c9-86d7-6f7decd2b2e3"}, {"title": "高霸率海陵军民迁广陵", "start_year": 887, "end_year": 887, "time_original": "光启三年壬寅至戊戌；月份未重标", "dynasty": "唐", "description": "杨行密忧孙儒进取海陵，命高霸率军民撤回广陵，并以族诛相胁；大批居民弃产迁徙。戊戌高霸与其弟暀、余绕山、丁从实抵广陵，杨行密出城迎接。", "phases": [], "location_name": "海陵、广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "55fde37f-393c-58aa-876f-ab9c1708152f"}, {"title": "秦宗权攻陷郑州", "start_year": 887, "end_year": 887, "time_original": "光启三年己亥；月份未重标", "dynasty": "唐", "description": "秦宗权攻陷郑州。", "phases": [], "location_name": "郑州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9a13609b-9f4b-5ec0-9543-e482622237aa"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

